(function(){
'use strict';
const C=window.THCore,K=window.THCreator;if(!C||!K||!window.TECH_HORIZON)return;
const $=(q,r=document)=>r.querySelector(q),$$=(q,r=document)=>[...r.querySelectorAll(q)],E=C.escape;
const original=window.TECH_HORIZON,draft=C.storage.get('th-draft',null),validDraft=draft&&C.validate(draft).length===0;
const D=C.storage.get('th-preview',false)&&validDraft?draft:original,base=document.body.dataset.base||'',page=document.body.dataset.page||'';
if(page==='kit'&&D!==original&&window.THCreatorMarkup)document.querySelector('main.command-page').innerHTML=window.THCreatorMarkup.body(page,D,C,K);
let toastTimer;function toast(text){const el=$('#toast');if(el){el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}}
function download(name,value,type='application/json;charset=utf-8'){const a=document.createElement('a'),blob=value instanceof Blob?value:new Blob([value],{type});a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),15000);}
const applyPreferences=window.THApplyPreferences;
const pref=applyPreferences(C.storage.get('th-preferences',null));
document.querySelectorAll('.command-shortcuts a').forEach(a=>{if(a.getAttribute('href')===location.pathname.split('/').pop())a.setAttribute('aria-current','page');});
const vietnamToday=()=>new Date(Date.now()+7*3600000).toISOString().slice(0,10);
if(page==='planner'){
 let data={version:1,tasks:[]},blocked=false,editing='',dirty=false,calendarView=false,savedRaw=null;const [year,month]=vietnamToday().split('-').map(Number);let shownYear=year,shownMonth=month-1;
 try{const raw=localStorage.getItem('th-planner');savedRaw=raw;if(raw)data=K.planner(JSON.parse(raw));}catch{blocked=true;const warning=$('#planner-storage-warning');warning.hidden=false;warning.textContent='Chưa đọc được kế hoạch đã lưu, hoặc trình duyệt chặn bộ nhớ. Hãy mở Dữ liệu & hiển thị để giữ bản dữ liệu thô hoặc khôi phục bản sao trước khi tiếp tục.';$('#new-task').disabled=true;}
 const dialog=$('#task-dialog'),form=$('#task-form'),fields=['title','format','stage','due','notes','sources','url'];
 function persist(next){try{if(blocked)throw Error('Tải lại trang hoặc khôi phục dữ liệu trước khi lưu kế hoạch.');if(localStorage.getItem('th-planner')!==savedRaw){blocked=true;throw Error('Kế hoạch đã thay đổi ở tab khác. Tải lại trang để giữ dữ liệu mới.');}const checked=K.planner(next);if(!C.storage.set('th-planner',checked))throw Error('Trình duyệt chưa lưu được kế hoạch. Hãy kiểm tra dung lượng hoặc quyền lưu dữ liệu.');data=checked;savedRaw=JSON.stringify(checked);render();return true;}catch(err){$('#task-status').textContent=err.message;toast(err.message);return false;}}
 function filtered(){const q=C.normalize($('#planner-query').value),format=$('#planner-format').value,period=$('#planner-period').value,now=Date.now();return data.tasks.filter(t=>(format==='all'||t.format===format)&&(!q||C.normalize(t.title+' '+t.notes+' '+t.sources).includes(q))&&(period==='all'||period==='unscheduled'&&!t.due||period==='overdue'&&t.stage!=='published'&&t.due&&K.localDate(t.due)<now||period==='upcoming'&&t.stage!=='published'&&t.due&&K.localDate(t.due)>=now&&K.localDate(t.due)<now+7*86400000)).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')||b.updated.localeCompare(a.updated));}
 function taskCard(t,compact=false){const overdue=t.due&&t.stage!=='published'&&K.localDate(t.due)<Date.now();return `<article class="planner-card ${overdue?'is-overdue':''}"><span class="task-format">${E(K.formats.find(([id])=>id===t.format)[1])}</span><button class="task-open" data-edit-task="${t.id}">${E(t.title)}</button>${t.due?`<time datetime="${t.due}+07:00">${E(t.due.slice(8,10)+'/'+t.due.slice(5,7)+' · '+t.due.slice(11))}${overdue?' · Qua mốc':''}</time>`:'<small>Chưa đặt ngày</small>'}${!compact?`<label class="sr-only" for="move-${t.id}">Trạng thái ${E(t.title)}</label><select id="move-${t.id}" data-move-task="${t.id}">${K.stages.map(([id,name])=>`<option value="${id}" ${t.stage===id?'selected':''}>${name}</option>`).join('')}</select>`:''}</article>`;}
 function render(){const list=filtered(),now=Date.now();$('#planner-total').textContent=data.tasks.length;$('#planner-ready').textContent=data.tasks.filter(t=>t.stage==='ready').length;$('#planner-upcoming').textContent=data.tasks.filter(t=>t.stage!=='published'&&t.due&&K.localDate(t.due)>=now&&K.localDate(t.due)<now+7*86400000).length;$('#planner-overdue').textContent=data.tasks.filter(t=>t.stage!=='published'&&t.due&&K.localDate(t.due)<now).length;$('#planner-result-count').textContent=list.length+' / '+data.tasks.length+' mục · Giờ Việt Nam (UTC+7)';
 for(const[id]of K.stages){const items=list.filter(t=>t.stage===id);$('[data-stage-count="'+id+'"]').textContent=items.length;$('[data-stage-list="'+id+'"]').innerHTML=items.map(t=>taskCard(t)).join('')||'<p class="column-empty">Chưa có mục</p>';}
 $('#planner-board').hidden=calendarView;$('#planner-calendar').hidden=!calendarView;$('#planner-empty').hidden=list.length>0||blocked;$('#planner-view').setAttribute('aria-pressed',String(calendarView));$('#planner-view').textContent=calendarView?'Xem bảng tiến độ':'Xem lịch tháng';$('#planner-ics').disabled=!list.some(t=>t.due);$('#planner-csv').disabled=!list.length;
 $('#calendar-month').textContent='Tháng '+(shownMonth+1)+' / '+shownYear;const cells=K.monthCells(shownYear,shownMonth),today=vietnamToday();$('#calendar-grid').innerHTML=cells.map(cell=>{const items=list.filter(t=>t.due.slice(0,10)===cell.date);return `<div class="calendar-day ${cell.current?'':'outside'} ${cell.date===today?'today':''}"><button class="calendar-day-number" data-new-date="${cell.date}" aria-label="Thêm kế hoạch ngày ${cell.date}">${cell.day}</button>${items.slice(0,3).map(t=>`<button class="calendar-event" data-edit-task="${t.id}" title="${E(t.title)}"><time>${t.due.slice(11)}</time>${E(t.title)}</button>`).join('')}${items.length>3?`<button class="calendar-more" data-open-day="${cell.date}">+${items.length-3} mục</button>`:''}</div>`;}).join('');
 const monthly=list.filter(t=>t.due.startsWith(shownYear+'-'+String(shownMonth+1).padStart(2,'0')));$('#calendar-mobile-list').innerHTML=monthly.map(t=>taskCard(t,true)).join('')||'<p class="column-empty">Không có mục phù hợp trong tháng này.</p>';$('#month-previous').disabled=shownYear===2000&&shownMonth===0;$('#month-next').disabled=shownYear===2099&&shownMonth===11;
 }
 function openTask(id='',date=''){if(blocked)return;const task=id?data.tasks.find(t=>t.id===id):null;if(id&&!task)return;editing=id;form.reset();for(const key of fields)form.elements.namedItem(key).value=task?task[key]:(key==='stage'?'idea':key==='format'?'post':key==='due'&&date?date+'T09:00':'');$('#task-dialog-title').textContent=task?'Chỉnh kế hoạch':'Một ý tưởng mới';$('#task-delete').hidden=!task;$('#task-duplicate').hidden=!task;$('#task-status').textContent='';dirty=false;dialog.showModal();$('#task-title').focus();}
 function closeTask(){if(dirty&&!confirm('Bỏ thay đổi chưa lưu trong kế hoạch này?'))return;dirty=false;dialog.close();}
 $('#new-task').addEventListener('click',()=>openTask());$$('[data-new-task]').forEach(b=>b.addEventListener('click',()=>openTask()));$('#close-task').addEventListener('click',closeTask);dialog.addEventListener('cancel',e=>{e.preventDefault();closeTask();});form.addEventListener('input',()=>dirty=true);form.addEventListener('change',()=>dirty=true);
 form.addEventListener('submit',e=>{e.preventDefault();const now=new Date().toISOString(),old=data.tasks.find(t=>t.id===editing),id=old?.id||(window.crypto?.randomUUID?.()||'task-'+Date.now()+'-'+Math.random().toString(16).slice(2));const task={id,created:old?.created||now,updated:now,...Object.fromEntries(fields.map(k=>[k,form.elements.namedItem(k).value.trim()]))};const tasks=old?data.tasks.map(t=>t.id===id?task:t):[...data.tasks,task];if(persist({version:1,tasks})){dirty=false;dialog.close();toast('Đã lưu kế hoạch trên thiết bị này.');}});
 $('#task-delete').addEventListener('click',()=>{if(!editing||!confirm('Xóa kế hoạch này khỏi trình duyệt?'))return;if(persist({version:1,tasks:data.tasks.filter(t=>t.id!==editing)})){dirty=false;dialog.close();toast('Đã xóa kế hoạch.');}});
 $('#task-duplicate').addEventListener('click',()=>{if(!editing)return;editing='';$('#task-dialog-title').textContent='Nhân bản thành kế hoạch mới';$('#task-title').value=($('#task-title').value+' (bản sao)').slice(0,180);$('#task-stage').value='idea';$('#task-url').value='';$('#task-delete').hidden=true;$('#task-duplicate').hidden=true;dirty=true;$('#task-status').textContent='Nhấn Lưu kế hoạch để tạo mục mới.';});
 document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-task]'),add=e.target.closest('[data-new-date]'),more=e.target.closest('[data-open-day]');if(edit)openTask(edit.dataset.editTask);if(add)openTask('',add.dataset.newDate);if(more){$('#calendar-mobile-list').classList.add('show-day-list');$('#calendar-mobile-list').innerHTML=filtered().filter(t=>t.due.startsWith(more.dataset.openDay)).map(t=>taskCard(t,true)).join('');$('#calendar-mobile-list').scrollIntoView({block:'nearest'});}});
 $('#planner-board').addEventListener('change',e=>{const id=e.target.dataset.moveTask;if(!id)return;const next={version:1,tasks:data.tasks.map(t=>t.id===id?{...t,stage:e.target.value,updated:new Date().toISOString()}:t)};if(!persist(next))render();});
 for(const id of ['planner-query','planner-format','planner-period'])$('#'+id).addEventListener(id==='planner-query'?'input':'change',render);
 $('#planner-view').addEventListener('click',()=>{calendarView=!calendarView;render();});
 for(const[id,step]of [['month-previous',-1],['month-next',1]])$('#'+id).addEventListener('click',()=>{shownMonth+=step;if(shownMonth<0){shownMonth=11;shownYear--;}if(shownMonth>11){shownMonth=0;shownYear++;}render();});$('#month-today').addEventListener('click',()=>{const[y,m]=vietnamToday().split('-').map(Number);shownYear=y;shownMonth=m-1;render();});
 $('#planner-ics').addEventListener('click',()=>{try{download('Tech_Horizon_Ke_Hoach.ics',K.calendar({version:1,tasks:filtered()}),'text/calendar;charset=utf-8');toast('Đã tạo tệp lịch. Nhập tệp vào ứng dụng lịch của bạn.');}catch(err){toast(err.message);}});$('#planner-csv').addEventListener('click',()=>download('Tech_Horizon_Ke_Hoach.csv',K.csv({version:1,tasks:filtered()}),'text/csv;charset=utf-8'));
 window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});render();
}
if(page==='settings'){
 $('#preference-scale').value=String(pref.scale);$('#preference-motion').value=pref.motion;$('#preference-contrast').checked=pref.contrast;
 $('#preferences-form').addEventListener('submit',e=>{e.preventDefault();const p={scale:Number($('#preference-scale').value),motion:$('#preference-motion').value,contrast:$('#preference-contrast').checked};if(C.storage.set('th-preferences',p)){applyPreferences(p);$('#preferences-status').textContent='Đã lưu tùy chọn trên thiết bị này.';}else $('#preferences-status').textContent='Trình duyệt chưa lưu được tùy chọn.';});
 let pending=null,pendingRaw=null;const selected=()=>$$('[data-backup-group]:checked').map(x=>x.dataset.backupGroup),status=text=>$('#device-status').textContent=text;
 function groupStats(){for(const[group,list]of Object.entries(K.groups)){let count=0,bytes=0;try{for(const key of list){const value=localStorage.getItem(key);if(value!==null){count++;bytes+=new Blob([value]).size;}}$('[data-group-detail="'+group+'"]').textContent=count+' mục lưu · '+(bytes/1024).toLocaleString('vi-VN',{maximumFractionDigits:1})+' KB nội dung JSON';}catch{$('[data-group-detail="'+group+'"]').textContent='Trình duyệt chưa cho đọc bộ nhớ';}}const date=C.storage.get('th-last-backup',null);if(typeof date==='string'&&Number.isFinite(Date.parse(date)))$('#backup-last').textContent='Lần bấm tải sao lưu gần nhất: '+new Date(date).toLocaleString('vi-VN')+'. Hãy kiểm tra tệp đã được tải xuống.';}
 function snapshot(){const data={};for(const group of selected())for(const key of K.groups[group]){const raw=localStorage.getItem(key);data[key]=raw===null?null:JSON.parse(raw);}return K.backup({type:'tech-horizon-device',version:1,exported:new Date().toISOString(),data},D.articles.map(a=>a.id));}
 $('#export-device').addEventListener('click',()=>{try{if(!selected().length)throw Error('Chọn ít nhất một nhóm dữ liệu.');const data=snapshot();download('Tech_Horizon_Sao_Luu_Thiet_Bi.json',JSON.stringify(data,null,2));C.storage.set('th-last-backup',new Date().toISOString());groupStats();status('Đã tạo bản sao lưu. Giữ tệp ở nơi riêng tư và kiểm tra tải xuống.');}catch(err){status('Chưa xuất được bản sao hợp lệ: '+err.message+' Có thể tải dữ liệu thô bằng nút bên dưới để giữ lại khi cần phục hồi.');}});
 $('#import-device').addEventListener('change',async e=>{pending=null;pendingRaw=null;$('#restore-preview').hidden=true;try{const file=e.target.files[0];if(!file)return;if(file.size>8*1024*1024)throw Error('Tệp vượt quá 8 MB.');pending=K.backup(JSON.parse(await file.text()),D.articles.map(a=>a.id));pendingRaw=K.capture(localStorage);const groups=Object.keys(K.groups).filter(g=>K.groups[g].some(k=>Object.hasOwn(pending.data,k)));$('#restore-description').textContent='Bản sao tạo lúc '+new Date(pending.exported).toLocaleString('vi-VN')+'.';$('#restore-groups').textContent='Có các nhóm: '+groups.map(g=>K.groupNames[g]).join(', ')+'.';$('#restore-preview').hidden=false;status('Đã kiểm tra tệp. Chưa thay đổi dữ liệu trên trình duyệt.');}catch(err){status('Không thể mở bản sao: '+err.message);}finally{e.target.value='';}});
 $('#cancel-restore').addEventListener('click',()=>{pending=null;$('#restore-preview').hidden=true;status('Đã hủy khôi phục.');});$('#restore-device').addEventListener('click',()=>{if(!pending)return;try{const chosen=selected();if(!chosen.length)throw Error('Chọn ít nhất một nhóm.');if(!confirm('Thay dữ liệu của các nhóm đang chọn và có trong tệp sao lưu? Nội dung hiện tại của các nhóm đó sẽ bị thay thế.'))return;const count=K.restore(localStorage,pending,chosen,D.articles.map(a=>a.id),pendingRaw);C.storage.remove('th-preview');status('Đã khôi phục '+count+' mục. Đang tải lại trang…');setTimeout(()=>location.reload(),600);}catch(err){status(err.message);}});
 $('#clear-selected').addEventListener('click',()=>{const chosen=selected();if(!chosen.length){status('Chọn ít nhất một nhóm để xóa.');return;}try{const list=chosen.flatMap(g=>K.groups[g]),expected=K.capture(localStorage,list);if(!confirm('Xóa dữ liệu của các nhóm này trên thiết bị: '+chosen.map(g=>K.groupNames[g]).join(', ')+'. Hãy chắc rằng bạn đã tải sao lưu.'))return;const empty=Object.fromEntries(list.map(k=>[k,null]));K.restore(localStorage,{type:'tech-horizon-device',version:1,exported:new Date().toISOString(),data:empty},chosen,D.articles.map(a=>a.id),expected);C.storage.remove('th-preview');location.reload();}catch(err){status(err.message);}});
 const rawButton=document.createElement('button');rawButton.className='text-button';rawButton.textContent='Tải dữ liệu thô để giữ bản phục hồi ↗';$('#device-status').after(rawButton);rawButton.addEventListener('click',()=>{try{const raw={type:'tech-horizon-recovery-raw',exported:new Date().toISOString(),data:Object.fromEntries(K.keys.map(k=>[k,localStorage.getItem(k)]))};download('Tech_Horizon_Du_Lieu_Tho.json',JSON.stringify(raw,null,2));status('Đây là bản giữ dữ liệu thô để phục hồi thủ công, không nhập trực tiếp như bản sao lưu chuẩn.');}catch{status('Trình duyệt đang chặn đọc dữ liệu.');}});
 const checked=validDraft?draft:original;$('#health-results').innerHTML='<p class="command-caption">Đang kiểm tra '+(validDraft?'bản nháp đã lưu trên trình duyệt':'nội dung đang xuất bản')+'.</p>'+K.health(checked).map(item=>'<div class="health-row"><span class="health-state '+(item.ok?'ok':'pending')+'">'+(item.ok?'✓':'○')+'</span><div><strong>'+E(item.label)+'</strong><p>'+E(item.detail)+'</p></div><span>'+(item.ok?'Đã có':'Cần bổ sung')+'</span></div>').join('');groupStats();
}
if(page==='kit'){
 $('#download-kit').addEventListener('click',()=>download('Tech_Horizon_Gioi_Thieu.txt',K.mediaKit(D),'text/plain;charset=utf-8'));
 $('#brief-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget,sender=form.elements.namedItem('sender').value.trim(),kind=form.elements.namedItem('kind').value,message=form.elements.namedItem('message').value.trim();if(!sender||!message)return;const text='Xin chào '+D.config.name+',\n\nTôi là '+sender+'.\nTôi muốn trao đổi: '+kind+'.\n\n'+message+'\n\nCảm ơn bạn!';$('#brief-output').value=text;$('#copy-brief').disabled=false;const email=$('#email-brief');email.hidden=!D.config.email;if(D.config.email)email.href='mailto:'+encodeURIComponent(D.config.email)+'?subject='+encodeURIComponent('[Tech Horizon] '+kind)+'&body='+encodeURIComponent(text);$('#brief-status').textContent='Đã soạn nội dung. Bạn xem lại rồi chủ động gửi; website chưa gửi tin nhắn.';});
 $('#copy-brief').addEventListener('click',async()=>{const field=$('#brief-output');try{if(navigator.clipboard&&isSecureContext)await navigator.clipboard.writeText(field.value);else{field.focus();field.select();if(!document.execCommand('copy'))throw Error('copy');}$('#brief-status').textContent='Đã sao chép. Bạn có thể dán vào kênh liên hệ chính thức.';}catch{field.focus();field.select();$('#brief-status').textContent='Nhấn Ctrl + C hoặc dùng lệnh sao chép trên thiết bị.';}});
}
window.addEventListener('storage',e=>{if(e.key==='th-preferences')applyPreferences(C.storage.get('th-preferences',null));if(page==='planner'&&e.key==='th-planner'){const warning=$('#planner-storage-warning');warning.hidden=false;warning.textContent='Kế hoạch đã thay đổi ở tab khác. Tải lại trang trước khi tiếp tục để tránh ghi đè dữ liệu mới.';$('#new-task').disabled=true;$('#planner-board').inert=true;$('#planner-calendar').inert=true;$('#task-form').inert=true;}});
})();
